import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'

import { permanentlyMount } from 'lib/utils/kea-logic-builders'

import { TaxonomicFilterGroupType } from './types'

export interface LastCategoryState {
    pathname: string | null
    categoryByKey: Record<string, TaxonomicFilterGroupType>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterLastCategoryLogicValues {
    lastCategories: LastCategoryState
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterLastCategoryLogicActions {
    rememberCategory: (
        key: string,
        category: TaxonomicFilterGroupType
    ) => {
        category: TaxonomicFilterGroupType
        key: string
        pathname: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taxonomicFilterLastCategoryLogicMeta {
    __keaTypeGenInternalReducerActions: {
        'location changed (kea.router)': ({
            method,
            pathname,
            search,
            searchParams,
            hash,
            hashParams,
            initial,
            url,
            routerState,
        }: LocationChangedPayload) => {
            payload: {
                hash: string
                hashParams: Record<string, any>
                initial: boolean
                method: 'POP' | 'PUSH' | 'REPLACE'
                pathname: string
                routerState: Record<string, any>
                search: string
                searchParams: Record<string, any>
                url: string
            }
            type: 'location changed (kea.router)'
        }
    }
}

export type taxonomicFilterLastCategoryLogicType = MakeLogicType<
    taxonomicFilterLastCategoryLogicValues,
    taxonomicFilterLastCategoryLogicActions,
    Record<string, any>,
    taxonomicFilterLastCategoryLogicMeta
>

const EMPTY_STATE: LastCategoryState = { pathname: null, categoryByKey: {} }

export const taxonomicFilterLastCategoryLogic = kea<taxonomicFilterLastCategoryLogicType>([
    path(['lib', 'components', 'TaxonomicFilter', 'taxonomicFilterLastCategoryLogic']),
    actions({
        rememberCategory: (key: string, category: TaxonomicFilterGroupType) => ({
            key,
            category,
            pathname: router.values.location.pathname,
        }),
    }),
    reducers(() => ({
        lastCategories: [
            EMPTY_STATE,
            {
                rememberCategory: (state, { key, category, pathname }) => ({
                    pathname,
                    categoryByKey: {
                        ...(state.pathname === pathname ? state.categoryByKey : {}),
                        [key]: category,
                    },
                }),
                // Pathname only: the insight editor rewrites the hash on every query edit, and that
                // must not count as leaving the page.
                [router.actionTypes.locationChanged]: (state, { pathname }) =>
                    state.pathname === null || state.pathname === pathname ? state : EMPTY_STATE,
            },
        ],
    })),
    // The memory must outlive each picker, because a picker unmounts when its popover closes.
    permanentlyMount(),
])
